'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const eq = (a, b) => assert.deepEqual(a, b);
eq(parse(''), []);
eq(parse('\uFEFF'), []);
eq(parse('\n'), [['']]);
eq(parse('\n\n'), [[''], ['']]);
eq(parse('a\n'), [['a']]);
eq(parse('a\r\nb\rc\nd'), [['a'], ['b'], ['c'], ['d']]);
eq(parse('\uFEFFa,\uFEFFb'), [['a', '\uFEFFb']]);
eq(parse('a"b,c""d'), [['a"b', 'c""d']]);
eq(parse('"x\r\ny\rz\n"'), [['x\r\ny\rz\n']]);
eq(parse('""'), [['']]);
eq(parse('a;"b;c"', { delimiter: ';' }), [['a', 'b;c']]);
eq(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
eq(parse('h,h\n1', { header: true }), [{ h: '1', h_2: '' }]);
eq(parse('', { header: true }), []);
for (const d of ['"', '\r', '\n', '', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
const lineOf = (fn, n) => assert.throws(fn, e => e instanceof SyntaxError && e.message.includes(`line ${n}`));
lineOf(() => parse('"a" ,b'), 1);
lineOf(() => parse('x\r\n"a\r\nb"c'), 3);
lineOf(() => parse('x\r\r\n\n"a'), 4);
lineOf(() => parse('"\r\n\r\n\n'), 4);

// lifecycle
const p = createParser();
assert.throws(() => p.push(1), TypeError);
eq(p.push('a\r'), [['a']]);
eq(p.push('\nb'), []);
eq(p.end(), [['b']]);
eq(p.end(), []);
assert.throws(() => p.push(''), Error);

// every 2-cut split matches the whole-input parse, including errors
const inputs = ['\uFEFFa,"b""c"\r\nd\r\r\n"e\r\nf",', '"x""""y"\n\n,', '"q\r\nr"z', '"a\r\n\r\nb', 'a,"b"\r\n"c"'];
const run = chunks => {
  const parser = createParser();
  const out = [];
  try {
    for (const c of chunks) out.push(...parser.push(c));
    out.push(...parser.end());
    return out;
  } catch (e) {
    return `${e.name}:${e.message}`;
  }
};
for (const s of inputs) {
  const whole = run([s]);
  for (let i = 0; i <= s.length; i++)
    for (let j = i; j <= s.length; j++)
      eq(run(['', s.slice(0, i), '', s.slice(i, j), s.slice(j)]), whole);
  eq(run([...s]), whole);
}
// records are emitted as soon as completed
const q = createParser();
eq(q.push('a,b\nc'), [['a', 'b']]);
eq(q.push('\r'), [['c']]);
console.log('smoke ok');
